args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?minBD WHERE {
  VALUES ?film { dbr:Angel_and_the_Badman dbr:Happy_Days_in_Aranjuez }
  {
    SELECT ?film (MIN(?bd) AS ?minBD) WHERE {
      VALUES ?film { dbr:Angel_and_the_Badman dbr:Happy_Days_in_Aranjuez }
      ?film (dbo:director|dbp:director) ?director .
      OPTIONAL { ?director dbo:birthDate ?b1 . }
      OPTIONAL { ?director dbp:birthDate ?b2 . }
      BIND(COALESCE(?b1, ?b2) AS ?bd)
      FILTER(bound(?bd))
    } GROUP BY ?film
  }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
}
ORDER BY ASC(?minBD)
LIMIT 1

